subject.mjs.source:
export function choose(value) {
  if (value) return 1
  return 0
}
export function unused() { return 9 }

serializer.mjs.source:
export default {
  test(value) { return value?.kind === 'special' },
  serialize(value) { return 'SPECIAL(' + value.value + ')' },
}

suite.test.mjs.source:
import {test,expect} from 'vitest'
import {choose} from './subject.mjs'
test('first owned body', () => {
  expect(globalThis.setupValue).toBe(0)
  expect(globalThis.hookValue).toBe(0)
  const value = choose(true)
  expect({kind:'special',value}).toMatchSnapshot()
})
test('second owned body', () => { expect(choose(false)).toBe(0) })

